package main
import("archive/zip";"context";"os";"path/filepath";"testing";"strings";"fmt";"net/http/httptest")
func manualZIPFixture(t *testing.T,path string,contents map[string]string){t.Helper();file,err:=os.Create(path);if err!=nil{t.Fatal(err)};writer:=zip.NewWriter(file);for name,content:=range contents{entry,err:=writer.Create(name);if err!=nil{t.Fatal(err)};if _,err=entry.Write([]byte(content));err!=nil{t.Fatal(err)}};if err=writer.Close();err!=nil{t.Fatal(err)};if err=file.Close();err!=nil{t.Fatal(err)}}
func TestManualBackupNestedInspection(t *testing.T){root:=t.TempDir();public:=filepath.Join(root,"public_html.zip");database:=filepath.Join(root,"databases.zip");archive:=filepath.Join(root,"website.zip");manualZIPFixture(t,public,map[string]string{"public_html/index.php":"<?php echo 'ok';","public_html/.htaccess":"deny","public_html/vendor/schema.sql":"CREATE TABLE application_template(id INT);"});manualZIPFixture(t,database,map[string]string{"example_db.sql":"CREATE TABLE example(id INT);"});if err:=zipBackupParts(archive,map[string]string{"public_html.zip":public,"databases.zip":database});err!=nil{t.Fatal(err)};stage:=t.TempDir();preview,err:=inspectManualBackup(context.Background(),archive,stage,fixtureBackupFreeBytes);if err!=nil{t.Fatal(err)};if preview.Files!=4||len(preview.Databases)!=1||preview.Databases[0]!="databases/example_db.sql"{t.Fatalf("incorrect preview: %+v",preview)};if _,err=os.Stat(filepath.Join(stage,"files","public_html",".htaccess"));err!=nil{t.Fatal("hidden file missing")};if _,err=os.Stat(filepath.Join(stage,"files","public_html","vendor","schema.sql"));err!=nil{t.Fatal("website SQL asset missing")}}
func TestManualBackupRejectsTraversalAndUnexpectedOuter(t *testing.T){for _,bad:=range []string{"../../escape.php","public_html/../../escape.php"}{t.Run(bad,func(t *testing.T){root:=t.TempDir();public:=filepath.Join(root,"public_html.zip");database:=filepath.Join(root,"databases.zip");archive:=filepath.Join(root,"website.zip");manualZIPFixture(t,public,map[string]string{bad:"unsafe"});manualZIPFixture(t,database,map[string]string{"README.txt":"no database"});if err:=zipBackupParts(archive,map[string]string{"public_html.zip":public,"databases.zip":database});err!=nil{t.Fatal(err)};if _,err:=inspectManualBackup(context.Background(),archive,t.TempDir(),fixtureBackupFreeBytes);err==nil{t.Fatal("unsafe archive accepted")}})};archive:=filepath.Join(t.TempDir(),"wrong.zip");manualZIPFixture(t,archive,map[string]string{"index.php":"wrong format"});if _,err:=inspectManualBackup(context.Background(),archive,t.TempDir(),fixtureBackupFreeBytes);err==nil{t.Fatal("wrong outer format accepted")}}
func TestManualBackupRestoreEndpointsRequireAuthentication(t *testing.T){app:=&App{};for _,path:=range []string{"/api/website-backups/upload","/api/website-backups/restore"}{response:=httptest.NewRecorder();app.routes().ServeHTTP(response,httptest.NewRequest("POST",path,nil));if response.Code!=401{t.Fatal(path,response.Code)}}}

func TestManualBackupRejectsSymlinks(t *testing.T){root:=t.TempDir();public:=filepath.Join(root,"public_html.zip");file,err:=os.Create(public);if err!=nil{t.Fatal(err)};writer:=zip.NewWriter(file);header:=&zip.FileHeader{Name:"public_html/link"};header.SetMode(os.ModeSymlink|0777);entry,err:=writer.CreateHeader(header);if err!=nil{t.Fatal(err)};entry.Write([]byte("/etc/shadow"));writer.Close();file.Close();database:=filepath.Join(root,"databases.zip");manualZIPFixture(t,database,map[string]string{"README.txt":"no databases"});archive:=filepath.Join(root,"website.zip");if err=zipBackupParts(archive,map[string]string{"public_html.zip":public,"databases.zip":database});err!=nil{t.Fatal(err)};if _,err=inspectManualBackup(context.Background(),archive,t.TempDir(),fixtureBackupFreeBytes);err==nil{t.Fatal("backup symlink accepted")}}

func TestManualBackupRestoresOnlyEmptyFixtureWebsite(t *testing.T){
 if os.Geteuid()!=0{t.Skip("managed ownership restore requires root fixture")}
 store,err:=OpenStore(t.TempDir());if err!=nil{t.Fatal(err)};system:=NewSystem(t.TempDir());system.manualBackupSpaceProbe=fixtureBackupFreeBytes;if system.demo{t.Skip("Linux restore fixture")}
 site:=Site{ID:"restore-fixture",Domain:"restore-fixture.test",Root:filepath.Join(t.TempDir(),"public"),AppType:"regular",RuntimeUID:os.Getuid(),RuntimeGID:os.Getgid()};if err=os.Mkdir(site.Root,0750);err!=nil{t.Fatal(err)};store.cfg.Sites=[]Site{site};app:=&App{store:store,system:system}
 root:=t.TempDir();public:=filepath.Join(root,"public_html.zip");database:=filepath.Join(root,"databases.zip");archive:=filepath.Join(root,"website.zip");manualZIPFixture(t,public,map[string]string{"public_html/index.html":"restored fixture","public_html/.htaccess":"fixture"});manualZIPFixture(t,database,map[string]string{"README.txt":"no database"});if err=zipBackupParts(archive,map[string]string{"public_html.zip":public,"databases.zip":database});err!=nil{t.Fatal(err)}
 preview,err:=app.prepareManualBackupStage(context.Background(),site,archive);if err!=nil{t.Fatal(err)}
 cached,err:=app.prepareManualBackupStage(context.Background(),site,archive);if err!=nil||cached.ID!=preview.ID{t.Fatal("same backup inspection was not reused")}
 restore:=func()int{request:=httptest.NewRequest("POST","/api/website-backups/restore?siteId="+site.ID,strings.NewReader(fmt.Sprintf(`{"action":"files","stageID":"%s","targetSiteID":"%s","confirm":true}`,preview.ID,site.ID)));response:=httptest.NewRecorder();app.websiteBackupRestore(response,request);if response.Code!=200&&response.Code!=409{t.Log(response.Body.String())};return response.Code}
 if code:=restore();code!=200{t.Fatal("empty fixture restore failed",code)};content,err:=os.ReadFile(filepath.Join(site.Root,"index.html"));if err!=nil||string(content)!="restored fixture"{t.Fatal("restored content mismatch")}
 if code:=restore();code!=409{t.Fatal("nonempty target accepted",code)};content,_=os.ReadFile(filepath.Join(site.Root,"index.html"));if string(content)!="restored fixture"{t.Fatal("existing data changed")}
}
